using IO.Infrastructure.Devices;
using Microsoft.AspNetCore.Antiforgery;
internal static class EnrollmentEndpoints
{
    internal static void MapEnrollment(this WebApplication app)
    {
        app.MapGet("/devices/attendance-range-erases",(HttpContext c,DeviceAttendanceErases service)=>GatewayEndpoints.Read(c,actor=>service.ListAsync(actor,c.RequestAborted,rangeOnly:true))).RequireAuthorization();
        app.MapPost("/devices/attendance-range-erases/preview",(DeviceAttendanceErases.Input input,HttpContext c,IAntiforgery csrf,DeviceAttendanceErases service)=>GatewayEndpoints.Admin(c,csrf,actor=>service.PreviewAsync(actor,input,c.RequestAborted,rangeOnly:true))).RequireAuthorization().WithMetadata(new Microsoft.AspNetCore.Mvc.RequestSizeLimitAttribute(16384));
        app.MapPost("/devices/attendance-range-erases",(DeviceAttendanceErases.Confirm input,HttpContext c,IAntiforgery csrf,DeviceAttendanceErases service)=>GatewayEndpoints.Admin(c,csrf,actor=>service.ProposeAsync(actor,input,c.RequestAborted,rangeOnly:true))).RequireAuthorization().WithMetadata(new Microsoft.AspNetCore.Mvc.RequestSizeLimitAttribute(16384));
        app.MapPost("/devices/attendance-range-erases/{id:guid}/approve",(Guid id,DeviceAttendanceErases.Review input,HttpContext c,IAntiforgery csrf,DeviceAttendanceErases service)=>GatewayEndpoints.Admin(c,csrf,actor=>service.ApproveAsync(actor,id,input,c.RequestAborted,rangeOnly:true))).RequireAuthorization().WithMetadata(new Microsoft.AspNetCore.Mvc.RequestSizeLimitAttribute(16384));
        app.MapPost("/devices/attendance-range-erases/{id:guid}/cancel",(Guid id,GatewayEndpoints.GatewayVersion input,HttpContext c,IAntiforgery csrf,DeviceAttendanceErases service)=>GatewayEndpoints.Admin(c,csrf,actor=>service.CancelAsync(actor,id,input.Version,c.RequestAborted,rangeOnly:true))).RequireAuthorization();
        app.MapGet("/devices/attendance-erases",(HttpContext c,DeviceAttendanceErases service)=>GatewayEndpoints.Read(c,actor=>service.ListAsync(actor,c.RequestAborted))).RequireAuthorization();
        app.MapPost("/devices/attendance-erases/preview",(DeviceAttendanceErases.Input input,HttpContext c,IAntiforgery csrf,DeviceAttendanceErases service)=>GatewayEndpoints.Admin(c,csrf,actor=>service.PreviewAsync(actor,input,c.RequestAborted))).RequireAuthorization().WithMetadata(new Microsoft.AspNetCore.Mvc.RequestSizeLimitAttribute(16384));
        app.MapPost("/devices/attendance-erases",(DeviceAttendanceErases.Confirm input,HttpContext c,IAntiforgery csrf,DeviceAttendanceErases service)=>GatewayEndpoints.Admin(c,csrf,actor=>service.ProposeAsync(actor,input,c.RequestAborted))).RequireAuthorization().WithMetadata(new Microsoft.AspNetCore.Mvc.RequestSizeLimitAttribute(16384));
        app.MapPost("/devices/attendance-erases/{id:guid}/approve",(Guid id,DeviceAttendanceErases.Review input,HttpContext c,IAntiforgery csrf,DeviceAttendanceErases service)=>GatewayEndpoints.Admin(c,csrf,actor=>service.ApproveAsync(actor,id,input,c.RequestAborted))).RequireAuthorization().WithMetadata(new Microsoft.AspNetCore.Mvc.RequestSizeLimitAttribute(16384));
        app.MapPost("/devices/attendance-erases/{id:guid}/cancel",(Guid id,GatewayEndpoints.GatewayVersion input,HttpContext c,IAntiforgery csrf,DeviceAttendanceErases service)=>GatewayEndpoints.Admin(c,csrf,actor=>service.CancelAsync(actor,id,input.Version,c.RequestAborted))).RequireAuthorization();
        app.MapGet("/devices/biometric-transfers/{id:guid}/recoveries",(Guid id,HttpContext c,DeviceBiometricRecovery service)=>GatewayEndpoints.Read(c,actor=>service.ListAsync(actor,id,c.RequestAborted))).RequireAuthorization();
        app.MapPost("/devices/biometric-recoveries",(DeviceBiometricRecovery.Input input,HttpContext c,IAntiforgery csrf,DeviceBiometricRecovery service)=>GatewayEndpoints.Admin(c,csrf,actor=>service.ProposeAsync(actor,input,c.RequestAborted))).RequireAuthorization().WithMetadata(new Microsoft.AspNetCore.Mvc.RequestSizeLimitAttribute(16384));
        app.MapPost("/devices/biometric-recoveries/{id:guid}/approve",(Guid id,DeviceBiometricRecovery.Review input,HttpContext c,IAntiforgery csrf,DeviceBiometricRecovery service)=>GatewayEndpoints.Admin(c,csrf,actor=>service.ApproveAsync(actor,id,input,c.RequestAborted))).RequireAuthorization().WithMetadata(new Microsoft.AspNetCore.Mvc.RequestSizeLimitAttribute(16384));
        app.MapGet("/devices/biometric-transfers",(int? offset,HttpContext c,DeviceBiometricTransfers service)=>GatewayEndpoints.Read(c,actor=>service.ListAsync(actor,offset??0,c.RequestAborted))).RequireAuthorization();
        app.MapPost("/devices/biometric-transfers/preview",(DeviceBiometricTransfers.Input input,HttpContext c,IAntiforgery csrf,DeviceBiometricTransfers service)=>GatewayEndpoints.Admin(c,csrf,actor=>service.PreviewAsync(actor,input,c.RequestAborted))).RequireAuthorization().WithMetadata(new Microsoft.AspNetCore.Mvc.RequestSizeLimitAttribute(16384));
        app.MapPost("/devices/biometric-transfers",(DeviceBiometricTransfers.Confirm input,HttpContext c,IAntiforgery csrf,DeviceBiometricTransfers service)=>GatewayEndpoints.Admin(c,csrf,actor=>service.RequestAsync(actor,input,c.RequestAborted))).RequireAuthorization().WithMetadata(new Microsoft.AspNetCore.Mvc.RequestSizeLimitAttribute(16384));
        app.MapPost("/devices/biometric-transfers/{id:guid}/cancel",(Guid id,GatewayEndpoints.GatewayVersion input,HttpContext c,IAntiforgery csrf,DeviceBiometricTransfers service)=>GatewayEndpoints.Admin(c,csrf,actor=>service.CancelAsync(actor,id,input.Version,c.RequestAborted))).RequireAuthorization();
        app.MapPost("/devices/push/preview",(DevicePushCommit.Input input,HttpContext c,IAntiforgery csrf,DevicePushCommit service)=>GatewayEndpoints.Admin(c,csrf,actor=>service.PreviewAsync(actor,input,c.RequestAborted))).RequireAuthorization();
        app.MapPost("/devices/push/commit",(DevicePushCommit.CommitInput input,HttpContext c,IAntiforgery csrf,DevicePushCommit service)=>GatewayEndpoints.Admin(c,csrf,actor=>service.CommitAsync(actor,input,c.RequestAborted))).RequireAuthorization();
        app.MapGet("/devices/enrollments/{id:guid}/recoveries",(Guid id,HttpContext c,RemoteEnrollmentRecovery service)=>GatewayEndpoints.Read(c,actor=>service.ListAsync(actor,id,c.RequestAborted))).RequireAuthorization();
        app.MapPost("/devices/enrollment-recoveries",(RemoteEnrollmentRecovery.Input input,HttpContext c,IAntiforgery csrf,RemoteEnrollmentRecovery service)=>GatewayEndpoints.Admin(c,csrf,actor=>service.ProposeAsync(actor,input,c.RequestAborted))).RequireAuthorization();
        app.MapPost("/devices/enrollment-recoveries/{id:guid}/approve",(Guid id,RemoteEnrollmentRecovery.Review input,HttpContext c,IAntiforgery csrf,RemoteEnrollmentRecovery service)=>GatewayEndpoints.Admin(c,csrf,actor=>service.ApproveAsync(actor,id,input,c.RequestAborted))).RequireAuthorization();
        app.MapGet("/devices/enrollments",(Guid? deviceId,int? offset,HttpContext c,RemoteEnrollments service)=>GatewayEndpoints.Read(c,actor=>service.ListAsync(actor,deviceId,offset??0,c.RequestAborted))).RequireAuthorization();
        app.MapPost("/devices/enrollments",(RemoteEnrollments.Input input,HttpContext c,IAntiforgery csrf,RemoteEnrollments service)=>GatewayEndpoints.Admin(c,csrf,actor=>service.RequestAsync(actor,input,c.RequestAborted))).RequireAuthorization().WithMetadata(new Microsoft.AspNetCore.Mvc.RequestSizeLimitAttribute(16384));
        app.MapPost("/devices/enrollments/{id:guid}/cancel",(Guid id,GatewayEndpoints.GatewayVersion input,HttpContext c,IAntiforgery csrf,RemoteEnrollments service)=>GatewayEndpoints.Admin(c,csrf,actor=>service.CancelAsync(actor,id,input.Version,c.RequestAborted))).RequireAuthorization();
    }
}
